import type { InstanceSummary } from '../domain/types'

/**
 * Events pushed by Main to the shell renderer (ADR-0015).
 *
 * `seq` is generated by Main, global to the app run, strictly increasing by 1 per
 * published event. It is not event sourcing: every event carries the full new
 * state (or the removed id), so applying the latest one is always enough.
 */
export type InstanceEvent =
  | { readonly seq: number; readonly type: 'instance.changed'; readonly instance: InstanceSummary }
  | { readonly seq: number; readonly type: 'instance.removed'; readonly instanceId: string }

/** State plus the `seq` it is consistent with. Events with seq <= snapshot.seq are already included. */
export interface InstancesSnapshot {
  readonly seq: number
  readonly instances: readonly InstanceSummary[]
}
